CREATE TABLE credit_accounts (id UUID PRIMARY KEY,hotel_id UUID NOT NULL REFERENCES hotels(id),customer_id UUID NOT NULL,credit_limit NUMERIC(19,4) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(id,hotel_id),UNIQUE(hotel_id,customer_id),FOREIGN KEY(customer_id,hotel_id) REFERENCES customers(id,hotel_id));
CREATE TABLE housekeeping_tasks (id UUID PRIMARY KEY,hotel_id UUID NOT NULL,branch_id UUID NOT NULL,room_id UUID NOT NULL,assigned_user_id UUID,task_date DATE NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('OPEN','IN_PROGRESS','DONE','CANCELLED')),notes VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(id,hotel_id,branch_id),FOREIGN KEY(room_id,hotel_id,branch_id) REFERENCES rooms(id,hotel_id,branch_id),FOREIGN KEY(branch_id,hotel_id) REFERENCES branches(id,hotel_id));
